@startuml

class Boeing {
  + name : string
}

class Airline {
  + name : string
  + registrationNumber : string
}

class Salesperson {
  + name : string
  + employeeId : int
}

class Contract {
  + contractId : string
  + deliveryConditions : string
  + legalAspects : string
}

class Acquisition {
  + model : string
  + price : float
  + deliveryDate : date
  + options : string
}

class Airplane {
  + serialNumber : string
  + modelType : string
  + status : string
}

Boeing "1" -- "0..*" Contract
Salesperson "1" -- "0..*" Contract
Contract "1" *-- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Airline "1" -- "0..*" Contract
Airline "0..1" o-- "0..*" Airline : daughterOf

@enduml

